async function getState() {
  const s = await app.snapshot()
  const ps = {}
  for (const [ref, info] of Object.entries(s.refs)) {
    const b = info.bounds
    if (info.role && info.role.toLowerCase().includes('section') && b && (b.right-b.left)===100 && (b.bottom-b.top)===75) {
      ps[ref] = { ref, left: b.left, top: b.top }
    }
  }
  let prog = ''
  const g = s.snapshot.grep('Progress', { context: 0 })
  const m = g.match(/Progress: [^"]*/)
  if (m) prog = m[0]
  return { pieces: ps, prog, snap: s }
}

function grabPoint(ref, ps) {
  const me = ps[ref]
  const others = Object.values(ps).filter(p => p.ref !== ref)
  let best = null
  for (let dy = 6; dy <= 69; dy += 3) {
    for (let dx = 6; dx <= 94; dx += 3) {
      const x = me.left + dx, y = me.top + dy
      let free = true
      for (const o of others) {
        if (x >= o.left-3 && x <= o.left+103 && y >= o.top-3 && y <= o.top+78) { free = false; break }
      }
      if (!free) continue
      // margin = distance to nearest occupied/outside point (approx via distance to piece border)
      const score = Math.min(dx, 100-dx, dy, 75-dy)
      if (!best || score > best.score) best = { x, y, score, dx, dy }
    }
  }
  return best
}

