}
async function doDrag(from, to) {
  await machine.mouseDown({ x: from.x, y: from.y })
  const steps = 5
  for (let i = 1; i <= steps; i++) {
    await machine.move({ x: Math.round(from.x + (to.x-from.x)*i/steps), y: Math.round(from.y + (to.y-from.y)*i/steps) })
  }
  await machine.mouseUp({ x: to.x, y: to.y })
  await wait({ waitTime: 0.4 })
}

async function spreadOnce(maxMoves) {
  let moves = 0
  while (moves < maxMoves) {
    const s = await getState()
    const ps = s.pieces
    const used = new Set()
    const unplaced = []
    for (const ref of Object.keys(ps)) {
      const i = atSlot(ps[ref])
      if (i >= 0 && !used.has(i)) { used.add(i) } else { unplaced.push(ref) }
    }
    if (unplaced.length === 0) { console.log('DONE spread. ' + s.prog); return true }
    // candidate pieces with grab points
    const cands = unplaced.map(ref => ({ ref, gp: grabPoint(ref, ps) })).filter(c => c.gp)
    if (cands.length === 0) { console.log('stuck: no grabbable piece'); return false }
    cands.sort((a,b) => b.gp.score - a.gp.score)
    const pick = cands[0]
    const unplacedRects = unplaced.filter(r => r !== pick.ref).map(r => ({ l: ps[r].left, t: ps[r].top }))
    let bestSlot = -1, bestCount = 1e9
    for (let i = 0; i < SLOTS.length; i++) {
      if (used.has(i)) continue
      const c = unplacedRects.filter(r => overlaps(SLOTS[i], r)).length
      if (c < bestCount) { bestCount = c; bestSlot = i }
    }
    const slot = SLOTS[bestSlot]
    const dx = slot.l - ps[pick.ref].left, dy = slot.t - ps[pick.ref].top
    await doDrag({ x: pick.gp.x, y: pick.gp.y }, { x: pick.gp.x + dx, y: pick.gp.y + dy })
    console.log(`moved ${pick.ref} -> slot${bestSlot} (${slot.l},${slot.t}) | ${s.prog}`)
    moves++
  }
  return false
}
