async function moveTo(ref, L, T) {
  const s = await getState()
  const ps = s.pieces
  const cur = ps[ref]
  if (!cur) { console.log('!! piece missing', ref); return null }
  if (Math.abs(cur.left-L)<=2 && Math.abs(cur.top-T)<=2) { console.log(`${ref} already at (${L},${T})`); return s.prog }
  const gp = grabPoint(ref, ps)
  if (!gp) { console.log('!! no grab point for', ref); return null }
  await doDrag({ x: gp.x, y: gp.y }, { x: gp.x + (L-cur.left), y: gp.y + (T-cur.top) })
  const s2 = await getState()
  const np = s2.pieces[ref]
  console.log(`${ref}: (${cur.left},${cur.top}) -> target(${L},${T}) landed(${np.left},${np.top})  ${s2.prog}`)
  return s2.prog
}

