async function tryPlace(ref, r, cc) {
  const before = gnum((await getState()).prog)
  const t = cell(r, cc)
  const prog = await moveTo(ref, t.l, t.t)
  const after = gnum(prog)
  if (after !== null && before !== null && after < before) {
    console.log(`✓ ${ref} FITS at (r${r},c${cc})  groups ${before} -> ${after}`)
    return true
  }
  console.log(`✗ ${ref} does NOT fit at (r${r},c${cc}) (groups still ${after})`)
  // park it somewhere free
  const st2 = await getState()
  for (const [pl, pt] of PARK) {
    let free = true
    for (const k of Object.keys(st2.pieces)) {
      if (k === ref) continue
      const p = st2.pieces[k]
      if (Math.abs(p.left - pl) < 100 && Math.abs(p.top - pt) < 75) { free = false; break }
    }
    if (free) { await moveTo(ref, pl, pt); break }
  }
  return false
}
